//! Julia: `azul.jl` (module `Azul`, generated by `doc/src/codegen/v2/lang_julia`).
//!
//! Spellings: the `ccall` layer keeps the C names (`Azul.AzCssProperty_textColor(..)`,
//! variant constructors `Azul.AzLayoutWidth_px(..)`), C-like enums are
//! `@enum` values (`Azul.AzLayoutDisplay_Flex`), structs have positional
//! isbits constructors that convert their arguments (`Azul.AzColorU(255, 0, 0, 255)`).
//! Unions are opaque blobs: the generated `az_union` builds the variant
//! struct BY FIELD NAME (`az_union(Azul.AzLayoutWidthValue,
//! Azul.AzLayoutWidthValueVariant_Exact, UInt8(6), ..)`: a variant whose
//! payload is less aligned than the union has a `_pad0` field between tag
//! and payload, like azul.h) and stores it into one;
//! `az_vec` copies the items into a Julia array and hands its pointer to
//! `Azul.AzXxxVec_copyFromPtr`; strings use `Azul.az_string`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, unicode_braced, variant_ctor_method, ExprSyntax,
    },
    lower_types::union_tag,
    CodegenBackend, GeneratedFile,
};

/// The Julia printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Julia;

impl ExprSyntax for Julia {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let f64_ty = ty == Prim::F64;
        match text {
            "nan" => String::from(if f64_ty { "NaN" } else { "NaN32" }),
            "inf" => String::from(if f64_ty { "Inf" } else { "Inf32" }),
            "-inf" => String::from(if f64_ty { "-Inf" } else { "-Inf32" }),
            _ if f64_ty => text.to_string(),
            _ => format!("{text}f0"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "Azul.az_string(\"{}\")",
            escape_quoted(s, &['$'], &unicode_braced)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("Azul.Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Azul.Az{ty}_{variant}")),
            EnumShape::Tagged => Doc::call(
                format!("Azul.Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            // By field name (`az_union`): azul.jl's variant struct may have
            // a `_pad0` field between tag and payload (azul.h's C layout).
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let mut a = vec![
                    Doc::text(format!("Azul.Az{ty}")),
                    Doc::text(format!("Azul.Az{ty}Variant_{variant}")),
                    Doc::text(format!("UInt8({tag})")),
                ];
                a.extend(args);
                Doc::call("az_union", a, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        Doc::call(
            format!("Azul.Az{ty}"),
            fields.into_iter().map(|(_, v)| v).collect(),
            broken,
        )
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("Azul.Az{ty}_create()"));
        }
        let mut args = vec![
            Doc::text(format!("Azul.Az{ty}_copyFromPtr")),
            Doc::text(format!("Azul.Az{elem}")),
        ];
        args.extend(items);
        Doc::call("az_vec", args, broken)
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("error({:?})", format!("not expressible: {what}")))
    }
}

const HELPERS: &str = r"# Copies the items into a Julia array; the C API clones them into the Vec.
function az_vec(copy, ::Type{T}, items...) where {T}
    arr = T[items...]
    GC.@preserve arr copy(pointer(arr), Csize_t(length(arr)))
end

# Unions are opaque blobs in azul.jl: build the variant struct V by field
# name (its tag, its payload if it has one, zeroes for the `_pad0` bytes
# azul.h puts between them when the payload is less aligned than the union)
# and store it into one.
function az_union(::Type{U}, ::Type{V}, tag, payload...) where {U,V}
    fields = map(fieldnames(V)) do f
        if f === :tag
            tag
        elseif f === :payload
            payload[1]
        else
            ntuple(_ -> 0x00, fieldcount(fieldtype(V, f)))
        end
    end
    variant = V(fields...)
    r = Ref{U}()
    GC.@preserve r unsafe_store!(Ptr{V}(Base.unsafe_convert(Ptr{U}, r)), variant)
    r[]
end
";

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Julia, item) {
        out.push_str(&format!("# {line}\n"));
    }
    let name = item.name.snake();
    match item_doc(&Julia, item) {
        Ok(doc) => out.push_str(&format!(
            "function {name}()\n    {}\nend\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "# not expressible with the Julia bindings: {reason}\n"
        )),
    }
    out
}

impl CodegenBackend for Julia {
    fn lang(&self) -> &'static str {
        "julia"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["jl"]
    }

    fn display_name(&self) -> &'static str {
        "Julia"
    }

    fn extension(&self) -> &'static str {
        "jl"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (Julia). Do not edit by hand.\n# Load the bindings \
             first: include(\"azul/azul.jl\"); using .Azul\n\n",
        );
        out.push_str(HELPERS);
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/azul.jl to azul/azul.jl, then: AZUL_LIB=$PWD/libazul.so julia \
             main.jl\ninclude(joinpath(@__DIR__, \"azul\", \"azul.jl\"))\nusing \
             .Azul\ninclude(joinpath(@__DIR__, \"styles.jl\"))\n",
        );
        for item in &m.items {
            let name = item.name.snake();
            main.push_str(&format!(
                "\n{name}_value = {name}()\nprintln(\"{name}: \", {name}_value.len, \" properties\")\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.jl".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.jl".to_string(),
                contents: main,
            },
        ]
    }
}
